const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Rough polygon for Sindh province, Pakistan
  var sindh = ee.Geometry.Polygon([
    [[66.0, 23.5], [72.0, 23.5], [72.0, 28.5], [66.0, 28.5], [66.0, 23.5]]
  ]);

  var date2019 = '2019-09-21';
  var date2020 = '2020-09-21';

  // 2. Data Acquisition - JRC Global Surface Water Monthly History
  var jrc2019 = ee.ImageCollection('JRC/GSW1_4/MonthlyHistory')
    .filterDate(date2019, '2019-09-22')
    .filterBounds(sindh);

  var jrc2020 = ee.ImageCollection('JRC/GSW1_4/MonthlyHistory')
    .filterDate(date2020, '2020-09-22')
    .filterBounds(sindh);

  // Check collection sizes
  var size2019 = jrc2019.size().getInfo();
  var size2020 = jrc2020.size().getInfo();

  console.log(`2019 Images: ${size2019}, 2020 Images: ${size2020}`);

  if (size2019 === 0 || size2020 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get the images
  var img2019 = jrc2019.first();
  var img2020 = jrc2020.first();

  // 3. Processing - Count water pixels (monthly classification: 2=water, 3=permanent water)
  var water2019 = img2019.eq(2).or(img2019.eq(3));
  var water2020 = img2020.eq(2).or(img2020.eq(3));

  // Count water pixels
  var count2019 = water2019.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sindh,
    scale: 1000,
    maxPixels: 1e9
  }).get('water').getInfo();

  var count2020 = water2020.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: sindh,
    scale: 1000,
    maxPixels: 1e9
  }).get('water').getInfo();

  console.log(`2019 Water Pixels: ${count2019}, 2020 Water Pixels: ${count2020}`);

  // Check for no valid pixels
  if (count2019 === null || count2020 === null || count2019 === 0 || count2020 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // 4. Calculation & Validation
  if (count2019 === null || count2020 === null || isNaN(count2019) || isNaN(count2020)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // 5. Final Answer
  var percentChange = ((count2020 - count2019) / count2019 * 100).toFixed(1);
  console.log(`Change: ${percentChange}%`);

  if (count2020 > count2019) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
